const j = $json || {};
const template = j.template || "cost-breakdown";
const validTemplates = [
  "stats-grid", "process-steps", "comparison", "timeline",
  "checklist", "cost-breakdown", "before-after-explanation", "faq-summary"
];
if (!validTemplates.includes(template)) {
  return {
    ok: false,
    errorCode: "INVALID_TEMPLATE",
    errorMessage: "template must be one of: " + validTemplates.join(", ")
  };
}
return {
  jobId: j.jobId || null,
  template,
  title: j.title || "Infographic",
  data: j.data || {},
  ok: true
};

const p = $("02 Validate Infographic Template").item.json;
const title = p.title || "Infographic";
const template = p.template;
const width = 1080;
const height = 1080;

const svgContent = `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}">
  <rect width="100%" height="100%" fill="#0f172a"/>
  <rect x="30" y="30" width="1020" height="1020" fill="none" stroke="#38bdf8" stroke-width="4" rx="24"/>
  <text x="60" y="120" fill="#38bdf8" font-family="sans-serif" font-size="40" font-weight="bold">${title.replace(/</g, '&lt;').replace(/>/g, '&gt;')}</text>
  <text x="60" y="180" fill="#94a3b8" font-family="sans-serif" font-size="24">Template: ${template}</text>
  <g transform="translate(60, 240)">
    <rect x="0" y="0" width="960" height="180" fill="#1e293b" rx="12"/>
    <text x="30" y="105" fill="#f8fafc" font-family="sans-serif" font-size="28">1. Analysis &amp; Research</text>
  </g>
  <g transform="translate(60, 460)">
    <rect x="0" y="0" width="960" height="180" fill="#1e293b" rx="12"/>
    <text x="30" y="105" fill="#f8fafc" font-family="sans-serif" font-size="28">2. Technical Cost Breakdown</text>
  </g>
  <g transform="translate(60, 680)">
    <rect x="0" y="0" width="960" height="180" fill="#1e293b" rx="12"/>
    <text x="30" y="105" fill="#f8fafc" font-family="sans-serif" font-size="28">3. Final Recommendations</text>
  </g>
</svg>`;

const binaryBuffer = Buffer.from(svgContent, "utf-8");
const base64Data = binaryBuffer.toString("base64");

return {
  json: {
    jobId: p.jobId,
    assetKey: `infographic-${template}-1`,
    assetType: "infographic",
    template,
    width,
    height,
    fileSizeBytes: binaryBuffer.length,
    mimeType: "image/svg+xml",
    ok: true
  },
  binary: {
    data: {
      data: base64Data,
      mimeType: "image/svg+xml",
      fileName: `infographic-${template}.svg`,
      fileExtension: "svg",
      fileSize: `${binaryBuffer.length} B`
    }
  }
};

const item = $input.item;
const meta = item.json || {};
const hasBinary = item.binary && item.binary.data && item.binary.data.data;

if (!hasBinary) {
  return {
    success: false,
    jobId: meta.jobId || null,
    status: "FAILED",
    message: "Infographic rendering failed — no binary image output produced.",
    data: null,
    warnings: [],
    errors: [{ code: "RENDER_FAILED", language: null, path: null, message: "Infographic renderer did not produce binary output data." }],
    nextAllowedActions: ["retry", "cancel"]
  };
}

return {
  success: true,
  jobId: meta.jobId,
  status: "ASSETS_READY",
  message: "Infographic rendered successfully using template: " + meta.template,
  data: {
    assetKey: meta.assetKey,
    assetType: meta.assetType,
    template: meta.template,
    width: meta.width,
    height: meta.height,
    fileSizeBytes: meta.fileSizeBytes,
    mimeType: meta.mimeType
  },
  warnings: [],
  errors: [],
  nextAllowedActions: ["optimize_images"]
};

const j = $json || {};
const code = j.errorCode || "INVALID_TEMPLATE";
const message = j.errorMessage || "Invalid infographic template selection.";
return {
  success: false,
  jobId: j.jobId || null,
  status: "FAILED",
  message,
  data: null,
  warnings: [],
  errors: [{ code, language: null, path: null, message }],
  nextAllowedActions: ["cancel"]
};
